<?php
declare(strict_types=1);
require_once __DIR__.'/global_brand_v704.php';

function do580_tid(): int {return function_exists('tenant_id')?(int)tenant_id():0;}
function do580_cid(): int {return function_exists('tenant_city_id')?(int)tenant_city_id():(function_exists('city_id')?(int)city_id():0);}
function do580_enabled(): bool {return !function_exists('setting_bool')||setting_bool('doctor_online_v580_enabled',true);}
function do580_json($v): string {return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'[]';}
function do580_decode($v,$fallback=[]){$x=json_decode((string)$v,true);return is_array($x)?$x:$fallback;}
function do580_slug(string $s): string {$s=mb_strtolower(trim($s));$s=preg_replace('/[^a-z0-9]+/u','-',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s)?:$s)??'';$s=trim($s,'-');return $s?:'item-'.substr(bin2hex(random_bytes(4)),0,8);}
function do580_safe_url(string $u): ?string {$u=trim($u);if($u==='')return null;if(str_starts_with($u,'/'))return $u;return filter_var($u,FILTER_VALIDATE_URL)?$u:null;}
function do580_table_exists(string $t): bool {try{$q=db()->prepare('SHOW TABLES LIKE ?');$q->execute([$t]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;}}
function do580_money(float $n): string {return 'Rs '.number_format($n,0);}
function do580_appointment_no(): string {return 'DOC-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));}
function do580_room_token(): string {return bin2hex(random_bytes(24));}
function do580_setting(string $k,string $d=''): string {return function_exists('setting')?(string)setting($k,$d):$d;}
function do580_setting_bool(string $k,bool $d=false): bool {return function_exists('setting_bool')?setting_bool($k,$d):$d;}
function do580_setting_int(string $k,int $d=0): int {return function_exists('setting_int')?setting_int($k,$d):$d;}

function do580_specialties(bool $active=true): array {try{$tid=do580_tid();$q=db()->prepare('SELECT * FROM health_specialties_v580 WHERE tenant_id IN (0,?)'.($active?' AND status=1':'').' ORDER BY tenant_id DESC,sort_order,name');$q->execute([$tid]);$seen=[];$out=[];foreach($q->fetchAll()?:[] as $r){$k=(string)$r['slug'];if(isset($seen[$k]))continue;$seen[$k]=1;$out[]=$r;}return $out;}catch(Throwable $e){return [];}}
function do580_specialty(int $id): ?array {try{$q=db()->prepare('SELECT * FROM health_specialties_v580 WHERE id=? LIMIT 1');$q->execute([$id]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_organizations(bool $active=true): array {try{$tid=do580_tid();$sql='SELECT * FROM health_organizations_v580 WHERE tenant_id=?'.($active?" AND status='active'":'').' ORDER BY verified DESC,name';$q=db()->prepare($sql);$q->execute([$tid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_org(int $id): ?array {try{$q=db()->prepare('SELECT * FROM health_organizations_v580 WHERE id=? AND tenant_id=? LIMIT 1');$q->execute([$id,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_doctor(int $id): ?array {try{$q=db()->prepare("SELECT d.*,s.name specialty_name,s.slug specialty_slug,o.name organization_name,o.org_type,o.area organization_area FROM health_doctors_v580 d LEFT JOIN health_specialties_v580 s ON s.id=d.specialty_id LEFT JOIN health_organizations_v580 o ON o.id=d.primary_org_id WHERE d.id=? AND d.tenant_id=? LIMIT 1");$q->execute([$id,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_doctor_by_user(int $uid): ?array {try{$q=db()->prepare("SELECT d.*,s.name specialty_name,o.name organization_name FROM health_doctors_v580 d LEFT JOIN health_specialties_v580 s ON s.id=d.specialty_id LEFT JOIN health_organizations_v580 o ON o.id=d.primary_org_id WHERE d.user_id=? AND d.tenant_id=? ORDER BY d.id DESC LIMIT 1");$q->execute([$uid,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_doctors(array $filters=[],int $limit=50): array {try{$tid=do580_tid();$where=["d.tenant_id=?","d.approval_status='approved'"];$p=[$tid];if(!empty($filters['specialty_id'])){$where[]='d.specialty_id=?';$p[]=(int)$filters['specialty_id'];}if(!empty($filters['org_id'])){$where[]='(d.primary_org_id=? OR EXISTS(SELECT 1 FROM health_doctor_orgs_v580 dx WHERE dx.doctor_id=d.id AND dx.organization_id=? AND dx.status=1))';$p[]=(int)$filters['org_id'];$p[]=(int)$filters['org_id'];}if(!empty($filters['online']))$where[]="d.online_status='available'";if(!empty($filters['q'])){$where[]='(d.display_name LIKE ? OR d.qualification LIKE ? OR s.name LIKE ? OR o.name LIKE ?)';$x='%'.trim((string)$filters['q']).'%';array_push($p,$x,$x,$x,$x);}if(!empty($filters['featured']))$where[]='d.featured=1';$order=!empty($filters['sort'])&&$filters['sort']==='fee'?'d.online_fee ASC':'d.featured DESC,d.online_status=\'available\' DESC,d.rating DESC,d.review_count DESC,d.display_name';$sql="SELECT d.*,s.name specialty_name,s.slug specialty_slug,o.name organization_name,o.area organization_area FROM health_doctors_v580 d LEFT JOIN health_specialties_v580 s ON s.id=d.specialty_id LEFT JOIN health_organizations_v580 o ON o.id=d.primary_org_id WHERE ".implode(' AND ',$where)." ORDER BY $order LIMIT ".max(1,min(200,$limit));$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_doctor_reviews(int $doctorId,int $limit=20): array {try{$q=db()->prepare("SELECT r.*,u.name patient_name FROM health_reviews_v580 r LEFT JOIN users u ON u.id=r.patient_user_id WHERE r.doctor_id=? AND r.status='published' ORDER BY r.id DESC LIMIT ".max(1,min(100,$limit)));$q->execute([$doctorId]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}

function do580_availability(int $doctorId): array {try{$q=db()->prepare('SELECT * FROM health_doctor_availability_v580 WHERE doctor_id=? AND tenant_id=? AND status=1 ORDER BY weekday,start_time');$q->execute([$doctorId,do580_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_slots(int $doctorId,int $days=10,string $mode='video'): array {$doc=do580_doctor($doctorId);if(!$doc)return [];$rows=do580_availability($doctorId);$by=[];foreach($rows as $r)$by[(int)$r['weekday']][]=$r;$out=[];$start=new DateTimeImmutable('today');for($i=0;$i<$days;$i++){$date=$start->modify('+'.$i.' day');$w=(int)$date->format('w');foreach($by[$w]??[] as $r){$rm=(string)$r['consultation_mode'];if($mode==='in_person'&&!in_array($rm,['in_person','both'],true))continue;if($mode!=='in_person'&&!in_array($rm,['online','both'],true))continue;$mins=max(10,(int)$r['slot_minutes']);$a=new DateTimeImmutable($date->format('Y-m-d').' '.substr((string)$r['start_time'],0,5));$b=new DateTimeImmutable($date->format('Y-m-d').' '.substr((string)$r['end_time'],0,5));for($t=$a;$t<$b;$t=$t->modify('+'.$mins.' minutes')){if($t<new DateTimeImmutable('+30 minutes'))continue;$out[]=['value'=>$t->format('Y-m-d H:i:s'),'label'=>$t->format('D, d M · h:i A'),'organization_id'=>(int)($r['organization_id']??0)];}}}if(!$out)return [];$busy=[];try{$q=db()->prepare("SELECT scheduled_at FROM health_appointments_v580 WHERE doctor_id=? AND tenant_id=? AND scheduled_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL ? DAY) AND status NOT IN ('cancelled','rejected','no_show')");$q->execute([$doctorId,do580_tid(),$days+1]);foreach($q->fetchAll()?:[] as $r)$busy[(new DateTimeImmutable((string)$r['scheduled_at']))->format('Y-m-d H:i')]=1;}catch(Throwable $e){}return array_values(array_filter($out,fn($s)=>empty($busy[(new DateTimeImmutable($s['value']))->format('Y-m-d H:i')])));}

function do580_patient_plan_active(int $uid): ?array {try{$q=db()->prepare("SELECT s.*,p.name plan_name,p.consultation_credits FROM health_subscriptions_v580 s JOIN health_subscription_plans_v580 p ON p.id=s.plan_id WHERE s.tenant_id=? AND s.user_id=? AND s.audience='patient' AND s.status='active' AND s.payment_status IN ('paid','waived') AND (s.ends_at IS NULL OR s.ends_at>=NOW()) ORDER BY s.ends_at DESC,id DESC LIMIT 1");$q->execute([do580_tid(),$uid]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_plans(string $audience='patient'): array {try{$tid=do580_tid();$q=db()->prepare('SELECT * FROM health_subscription_plans_v580 WHERE tenant_id IN (0,?) AND audience=? AND status=1 ORDER BY tenant_id DESC,sort_order,price');$q->execute([$tid,$audience]);$seen=[];$out=[];foreach($q->fetchAll()?:[] as $r){$k=(string)$r['slug'];if(isset($seen[$k]))continue;$seen[$k]=1;$out[]=$r;}return $out;}catch(Throwable $e){return [];}}

function do580_create_appointment(int $uid,array $d): int {$doctorId=(int)($d['doctor_id']??0);$doc=do580_doctor($doctorId);if(!$doc||$doc['approval_status']!=='approved')throw new RuntimeException('Doctor is not available for booking.');$mode=in_array((string)($d['consultation_mode']??''),['video','audio','chat','in_person'],true)?(string)$d['consultation_mode']:'video';$scheduled=trim((string)($d['scheduled_at']??''));if($scheduled==='')throw new RuntimeException('Choose an appointment slot.');$valid=false;foreach(do580_slots($doctorId,14,$mode) as $s)if($s['value']===$scheduled){$valid=true;break;}if(!$valid)throw new RuntimeException('That slot is no longer available. Please select another time.');$familyId=(int)($d['family_member_id']??0)?:null;$patientName=trim((string)($d['patient_name']??''));if($familyId){try{$q=db()->prepare('SELECT name FROM health_family_members_v580 WHERE id=? AND owner_user_id=? AND tenant_id=?');$q->execute([$familyId,$uid,do580_tid()]);$patientName=(string)($q->fetchColumn()?:$patientName);}catch(Throwable $e){}}if($patientName===''){$me=current_user();$patientName=(string)($me['name']??'Patient');}$fee=$mode==='in_person'?(float)$doc['clinic_fee']:(float)$doc['online_fee'];$feeSource='doctor';$payment='unpaid';$subId=null;$method=(string)($d['payment_method']??'manual');$sub=do580_patient_plan_active($uid);if($method==='subscription'&&$sub&&((int)$sub['remaining_consults']>0||((int)$sub['consultation_credits']===0))){$fee=0;$feeSource='subscription';$payment='paid';$subId=(int)$sub['id'];}$org=(int)($d['organization_id']??0)?:((int)($doc['primary_org_id']??0)?:null);$q=db()->prepare("INSERT INTO health_appointments_v580(tenant_id,city_id,appointment_no,doctor_id,organization_id,patient_user_id,family_member_id,patient_name,patient_phone,patient_email,consultation_mode,scheduled_at,duration_minutes,reason,private_patient_note,fee,fee_source,payment_method,payment_status,subscription_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'requested',NOW(),NOW())");$q->execute([do580_tid(),do580_cid(),do580_appointment_no(),$doctorId,$org,$uid,$familyId,$patientName,trim((string)($d['phone']??''))?:null,trim((string)($d['email']??''))?:null,$mode,$scheduled,max(10,(int)$doc['consultation_minutes']),mb_substr(trim((string)($d['reason']??'')),0,600),trim((string)($d['note']??''))?:null,$fee,$feeSource,$method,$payment,$subId]);$id=(int)db()->lastInsertId();if($subId&&$feeSource==='subscription'){db()->prepare('UPDATE health_subscriptions_v580 SET remaining_consults=IF(remaining_consults>0,remaining_consults-1,remaining_consults),updated_at=NOW() WHERE id=?')->execute([$subId]);}if($method==='online_payment'&&$fee>0&&function_exists('create_payment_order')){try{$pid=create_payment_order($uid,$fee,'doctor_online',null,null,null,'none',['health_appointment_id'=>$id]);db()->prepare("UPDATE health_appointments_v580 SET payment_order_id=?,payment_status='pending' WHERE id=?")->execute([$pid,$id]);}catch(Throwable $e){}}do580_track('appointment_created','appointment',$id,['doctor_id'=>$doctorId,'mode'=>$mode]);return $id;}

function do580_my_appointments(int $uid,int $limit=100): array {try{$q=db()->prepare("SELECT a.*,d.display_name doctor_name,d.photo_url,d.slug doctor_slug,s.name specialty_name,o.name organization_name FROM health_appointments_v580 a JOIN health_doctors_v580 d ON d.id=a.doctor_id LEFT JOIN health_specialties_v580 s ON s.id=d.specialty_id LEFT JOIN health_organizations_v580 o ON o.id=a.organization_id WHERE a.patient_user_id=? AND a.tenant_id=? ORDER BY a.scheduled_at DESC LIMIT ".max(1,min(200,$limit)));$q->execute([$uid,do580_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_doctor_appointments(int $doctorId,int $limit=200): array {try{$q=db()->prepare("SELECT a.*,u.name account_name FROM health_appointments_v580 a LEFT JOIN users u ON u.id=a.patient_user_id WHERE a.doctor_id=? AND a.tenant_id=? ORDER BY a.scheduled_at DESC LIMIT ".max(1,min(400,$limit)));$q->execute([$doctorId,do580_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_appointment(int $id): ?array {try{$q=db()->prepare("SELECT a.*,d.display_name doctor_name,d.user_id doctor_user_id,d.photo_url doctor_photo,d.qualification,d.registration_no,s.name specialty_name,o.name organization_name,o.address organization_address FROM health_appointments_v580 a JOIN health_doctors_v580 d ON d.id=a.doctor_id LEFT JOIN health_specialties_v580 s ON s.id=d.specialty_id LEFT JOIN health_organizations_v580 o ON o.id=a.organization_id WHERE a.id=? AND a.tenant_id=? LIMIT 1");$q->execute([$id,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_can_access_appointment(array $a,array $u): bool {if((int)$a['patient_user_id']===(int)$u['id']||(int)$a['doctor_user_id']===(int)$u['id'])return true;if(function_exists('has_permission')&&has_permission('health.consultations.manage',$u)){if(!function_exists('do580_staff_scope'))return true;$s=do580_staff_scope($u);if($s['all'])return true;if(in_array((int)$a['doctor_id'],$s['doctor_ids'],true))return true;if(!empty($a['organization_id'])&&in_array((int)$a['organization_id'],$s['org_ids'],true))return true;}return false;}
function do580_consultation_for_appointment(int $appointmentId): ?array {try{$q=db()->prepare('SELECT * FROM health_consultations_v580 WHERE appointment_id=? LIMIT 1');$q->execute([$appointmentId]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_ensure_consultation(array $a): array {$c=do580_consultation_for_appointment((int)$a['id']);if($c)return $c;try{db()->prepare("INSERT INTO health_consultations_v580(tenant_id,appointment_id,room_token,doctor_user_id,patient_user_id,status,created_at,updated_at) VALUES(?,?,?,?,?,'waiting',NOW(),NOW())")->execute([do580_tid(),(int)$a['id'],do580_room_token(),(int)$a['doctor_user_id'],(int)$a['patient_user_id']]);}catch(Throwable $e){}$c=do580_consultation_for_appointment((int)$a['id']);if(!$c)throw new RuntimeException('Consultation room could not be created.');return $c;}
function do580_prescription(int $appointmentId): ?array {try{$q=db()->prepare('SELECT * FROM health_prescriptions_v580 WHERE appointment_id=? LIMIT 1');$q->execute([$appointmentId]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}

function do580_dashboard_stats(?array $u=null): array {$s=['doctors'=>0,'online'=>0,'appointments_today'=>0,'appointments_30'=>0,'organizations'=>0,'patients'=>0,'consultations_30'=>0,'revenue_30'=>0.0];try{$tid=do580_tid();$params=[$tid];$count=function(string $sql,array $p) {try{$q=db()->prepare($sql);$q->execute($p);return $q->fetchColumn();}catch(Throwable $e){return 0;}};$s['doctors']=(int)$count("SELECT COUNT(*) FROM health_doctors_v580 WHERE tenant_id=? AND approval_status='approved'",$params);$s['online']=(int)$count("SELECT COUNT(*) FROM health_doctors_v580 WHERE tenant_id=? AND approval_status='approved' AND online_status='available'",$params);$s['appointments_today']=(int)$count("SELECT COUNT(*) FROM health_appointments_v580 WHERE tenant_id=? AND DATE(scheduled_at)=CURDATE() AND status NOT IN ('cancelled','rejected')",$params);$s['appointments_30']=(int)$count("SELECT COUNT(*) FROM health_appointments_v580 WHERE tenant_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)",$params);$s['organizations']=(int)$count("SELECT COUNT(*) FROM health_organizations_v580 WHERE tenant_id=? AND status='active'",$params);$s['patients']=(int)$count("SELECT COUNT(DISTINCT patient_user_id) FROM health_appointments_v580 WHERE tenant_id=?",$params);$s['consultations_30']=(int)$count("SELECT COUNT(*) FROM health_appointments_v580 WHERE tenant_id=? AND completed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)",$params);$s['revenue_30']=(float)$count("SELECT COALESCE(SUM(fee),0) FROM health_appointments_v580 WHERE tenant_id=? AND payment_status='paid' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)",$params);}catch(Throwable $e){}return $s;}
function do580_activity_days(int $days=14): array {$out=[];try{$q=db()->prepare("SELECT DATE(created_at) d,COUNT(*) n FROM health_activity_v580 WHERE tenant_id=? AND created_at>=DATE_SUB(CURDATE(),INTERVAL ? DAY) GROUP BY DATE(created_at) ORDER BY d");$q->execute([do580_tid(),$days]);$map=[];foreach($q->fetchAll()?:[] as $r)$map[$r['d']]=(int)$r['n'];for($i=$days-1;$i>=0;$i--){$d=date('Y-m-d',strtotime('-'.$i.' day'));$out[]=['d'=>$d,'n'=>$map[$d]??0];}}catch(Throwable $e){}return $out;}
function do580_track(string $event,string $entity='',?int $entityId=null,array $meta=[]): void {if(!do580_table_exists('health_activity_v580'))return;try{$u=current_user();$raw=(string)($_SERVER['REMOTE_ADDR']??'').(string)($_SERVER['HTTP_USER_AGENT']??'').date('Y-m-d');$hash=hash('sha256',$raw.'|doctor-online-v580');db()->prepare('INSERT INTO health_activity_v580(tenant_id,user_id,visitor_hash,event_type,entity_type,entity_id,meta_json,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([do580_tid(),$u?(int)$u['id']:null,$hash,$event,$entity?:null,$entityId,$meta?do580_json($meta):null]);}catch(Throwable $e){}}

function do580_public_header(string $title='Doctor Online',string $desc='Book doctors and online consultations.'): void {global $config;$brand=function_exists('gb704_brand_name')?gb704_brand_name('ShahkotPK'):(function_exists('tenant_brand')?tenant_brand('site_name','ShahkotPK'):($config['app_name']??'ShahkotPK'));$logo=function_exists('gb704_picture')?gb704_picture('doctor',$brand):'';$brandMarkup=$logo!==''?$logo.'<span class="gb704-module-label">Doctor Online</span>':'<span class="mark">＋</span><span><b>Doctor Online</b><small>'.e($brand).' Digital Healthcare</small></span>';$em=do580_setting('doctor_online_v580_emergency_number','1122');echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="'.e(csrf_token()).'"><title>'.e($title).' - '.e($brand).'</title><meta name="description" content="'.e($desc).'"><link rel="stylesheet" href="/assets/doctor-online-5.8.0.css?v=580">'.(function_exists('gb704_asset_tag')?gb704_asset_tag():'').'<script defer src="/assets/doctor-online-5.8.0.js?v=580"></script></head><body class="do580-body">'; require_once __DIR__.'/views/header.php'; }
function do580_public_footer(): void { require_once __DIR__.'/views/footer.php'; echo '</body></html>';}
function do580_staff_rows(int $uid): array {try{$q=db()->prepare('SELECT * FROM health_staff_v580 WHERE tenant_id=? AND user_id=? AND status=1');$q->execute([do580_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function do580_staff_scope(?array $u=null): array {$u=$u?:current_user();$out=['all'=>false,'doctor_ids'=>[],'org_ids'=>[],'roles'=>[]];if(!$u)return $out;if(function_exists('is_super_admin')&&is_super_admin($u)){$out['all']=true;return $out;}foreach(do580_staff_rows((int)$u['id']) as $r){$role=(string)$r['access_role'];$out['roles'][]=$role;if($role==='health_admin')$out['all']=true;if(!empty($r['doctor_id']))$out['doctor_ids'][]=(int)$r['doctor_id'];if(!empty($r['organization_id']))$out['org_ids'][]=(int)$r['organization_id'];}if($d=do580_doctor_by_user((int)$u['id']))$out['doctor_ids'][]=(int)$d['id'];$out['doctor_ids']=array_values(array_unique($out['doctor_ids']));$out['org_ids']=array_values(array_unique($out['org_ids']));$out['roles']=array_values(array_unique($out['roles']));return $out;}
function do580_can_manage_doctor(int $doctorId,?array $u=null): bool {$u=$u?:current_user();$s=do580_staff_scope($u);if($s['all'])return true;if(in_array($doctorId,$s['doctor_ids'],true))return true;if($s['org_ids']){try{$q=db()->prepare('SELECT primary_org_id FROM health_doctors_v580 WHERE id=? AND tenant_id=?');$q->execute([$doctorId,do580_tid()]);$oid=(int)$q->fetchColumn();if($oid&&in_array($oid,$s['org_ids'],true))return true;}catch(Throwable $e){}}return false;}
function do580_can_manage_org(int $orgId,?array $u=null): bool {$s=do580_staff_scope($u);return $s['all']||in_array($orgId,$s['org_ids'],true);}
function do580_staff_can_global(?array $u=null): bool {$s=do580_staff_scope($u);return $s['all']||in_array('subscription_manager',$s['roles'],true);}
function do580_doctor_subscription(int $doctorId): ?array {try{$q=db()->prepare("SELECT s.*,p.name plan_name FROM health_subscriptions_v580 s JOIN health_subscription_plans_v580 p ON p.id=s.plan_id WHERE s.doctor_id=? AND s.tenant_id=? AND s.audience='doctor' AND s.status='active' AND s.payment_status IN ('paid','waived') AND (s.ends_at IS NULL OR s.ends_at>=NOW()) ORDER BY s.ends_at DESC LIMIT 1");$q->execute([$doctorId,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_org_subscription(int $orgId): ?array {try{$q=db()->prepare("SELECT s.*,p.name plan_name FROM health_subscriptions_v580 s JOIN health_subscription_plans_v580 p ON p.id=s.plan_id WHERE s.organization_id=? AND s.tenant_id=? AND s.audience='organization' AND s.status='active' AND s.payment_status IN ('paid','waived') AND (s.ends_at IS NULL OR s.ends_at>=NOW()) ORDER BY s.ends_at DESC LIMIT 1");$q->execute([$orgId,do580_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function do580_update_rating(int $doctorId): void {try{$q=db()->prepare("SELECT COALESCE(AVG(rating),0),COUNT(*) FROM health_reviews_v580 WHERE doctor_id=? AND status='published'");$q->execute([$doctorId]);$r=$q->fetch(PDO::FETCH_NUM);db()->prepare('UPDATE health_doctors_v580 SET rating=?,review_count=?,updated_at=NOW() WHERE id=?')->execute([round((float)($r[0]??0),2),(int)($r[1]??0),$doctorId]);}catch(Throwable $e){}}
